/**
 * Starts the EXPRESS-010 app on a real port so you can send requests by hand.
 * Run: npm run dev:express:10   (restarts on every save)
 * Do not edit this file; write your solution in task10.ts.
 */
import type { NextFunction, Request, Response } from "express";
import { createApp, type AuthUser, type TokenVerifier } from "./task10";

const PORT = Number(process.env.PORT ?? 3000);

const USERS: Record<string, AuthUser> = {
  "token-alice": { id: "u-alice", role: "member" },
  "token-bob": { id: "u-bob", role: "member" },
  "token-root": { id: "u-root", role: "admin" },
};

const tokens: TokenVerifier = {
  async verify(token) {
    console.log(`verify(${JSON.stringify(token)})`);
    if (token === "token-down") throw new Error("login-service.internal: timeout");
    return USERS[token] ?? null;
  },
};

const app = createApp({ tokens });

// Runs only for errors your code does not handle itself: prints the full error
// in this terminal and returns it in the response, so a 500 shows what broke.
app.use((err: unknown, req: Request, res: Response, _next: NextFunction) => {
  console.error(`\n500 on ${req.method} ${req.originalUrl}\n`, err);
  const message = err instanceof Error ? err.message : String(err);
  res.status(500).json({ unhandledError: message });
});

app.listen(PORT, () => {
  console.log(`EXPRESS-010 running on http://localhost:${PORT}`);
  console.log("Tokens: token-alice, token-bob, token-root (token-down = login service is down)");
  console.log("Send requests from src/express/task10/requests.http");
});
